import {
	Component,
	Element,
	Event,
	EventEmitter,
	Fragment,
	Host,
	Listen,
	Method,
	Prop,
	Watch,
	h,
} from "@stencil/core";
import { offsetParent } from "composed-offset-position";
import { loadFloatingUi } from "../../utils/floating-ui";

/**
 * @since 1.0.30
 * @status stable
 *
 * @slot - The popup's content.
 * @slot anchor - The element the popup will be anchored to. If the anchor lives outside of the popup, you can use the
 *  `anchor` attribute or property instead.
 *
 * @part arrow - The arrow's container. Avoid setting `top|bottom|left|right` properties, as these values are
 *  assigned dynamically as the popup moves. This is most useful for applying a background color to match the popup, and
 *  maybe a border or box shadow.
 * @part popup - The popup's container. Useful for setting a background color, box shadow, etc.
 */

@Component({
	tag: "hbr-popup",
	styleUrl: "popup.scss",
	shadow: true,
})
export class HbrPopup {
	@Element() host: HTMLHbrPopupElement;
	currentPlacement: string | null = null;

	/**
	 * The element the popup will be anchored to. If the anchor lives outside of the popup, you can provide its `id` or a
	 * reference to it here. If the anchor lives inside the popup, use the `anchor` slot instead.
	 */
	@Prop() anchor: HTMLElement | string | SVGElement;

	/**
	 * Activates the positioning logic and shows the popup. When this attribute is removed, the positioning logic is torn
	 * down and the popup will be hidden.
	 */
	@Prop({ reflect: true }) active = false;

	/**
	 * The preferred placement of the popup. Note that the actual placement will vary as configured to keep the
	 * panel inside of the viewport.
	 */
	@Prop({ reflect: true }) placement:
		| "top"
		| "top-start"
		| "top-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "right"
		| "right-start"
		| "right-end"
		| "left"
		| "left-start"
		| "left-end" = "top";

	/**
	 * Determines how the popup is positioned. The `absolute` strategy works well in most cases, but if overflow is
	 * clipped, using a `fixed` position strategy can often workaround it.
	 */
	@Prop({ reflect: true }) strategy: "absolute" | "fixed" = "absolute";

	/** The distance in pixels from which to offset the panel away from its anchor. */
	@Prop() distance = 0;

	/** The distance in pixels from which to offset the panel along its anchor. */
	@Prop() skidding = 0;

	/**
	 * Attaches an arrow to the popup. The arrow's size and color can be customized using the `--arrow-size` and
	 * `--arrow-color` custom properties. For additional customizations, you can also target the arrow using
	 * `::part(arrow)` in your stylesheet.
	 */
	@Prop({ reflect: true }) arrow = false;

	/**
	 * Used to calculate the offset of the popup. offset = arrowSize + distance
	 * Same value as "--arrow-size" CSS prop, the CSS prop controls the arrow itself and property name "arrowSize" used to calculate offset
	 */
	@Prop({ reflect: true }) arrowSize = 6;

	/**
	 * The placement of the arrow. The default is `anchor`, which will align the arrow as close to the center of the
	 * anchor as possible, considering available space and `arrow-padding`. A value of `start`, `end`, or `center` will
	 * align the arrow to the start, end, or center of the popover instead.
	 */
	@Prop({ attribute: "arrow-placement" }) arrowPlacement:
		| "start"
		| "end"
		| "center"
		| "anchor" = "anchor";

	/**
	 * The amount of padding between the arrow and the edges of the popup. If the popup has a border-radius, for example,
	 * this will prevent it from overflowing the corners.
	 */
	@Prop({ reflect: true }) arrowPadding = 12;

	/**
	 * When set, placement of the popup will flip to the opposite site to keep it in view. You can use
	 * `flipFallbackPlacements` to further configure how the fallback placement is determined.
	 */
	@Prop() flip = false;

	/**
	 * TODO
	 * If the preferred placement doesn't fit, popup will be tested in these fallback placements until one fits. Must be a
	 * string of any number of placements separated by a space, e.g. "top bottom left". If no placement fits, the flip
	 * fallback strategy will be used instead.
	 * */
	// @Prop({mutable: true}) flipFallbackPlacements: string[] = [];

	/**
	 * When neither the preferred placement nor the fallback placements fit, this value will be used to determine whether
	 * the popup should be positioned using the best available fit based on available space or as it was initially
	 * preferred.
	 */
	@Prop() flipFallbackStrategy: "best-fit" | "initial" = "best-fit";

	/**
	 * The flip boundary describes clipping element(s) that overflow will be checked relative to when flipping. By
	 * default, the boundary includes overflow ancestors that will cause the element to be clipped. If needed, you can
	 * change the boundary by passing a reference to one or more elements to this property.
	 */
	@Prop() flipBoundary: HTMLElement | HTMLElement[];

	/** The amount of padding, in pixels, to exceed before the flip behavior will occur. */
	@Prop() flipPadding = 0;

	/** Moves the popup along the axis to keep it in view when clipped. */
	@Prop() shift = false;

	/** Enable popover, since 2.15.0 */
	@Prop() enablePopover = false;

	/**
	 * The shift boundary describes clipping element(s) that overflow will be checked relative to when shifting. By
	 * default, the boundary includes overflow ancestors that will cause the element to be clipped. If needed, you can
	 * change the boundary by passing a reference to one or more elements to this property.
	 */
	@Prop() shiftBoundary: HTMLElement | HTMLElement[];

	/** The amount of padding, in pixels, to exceed before the shift behavior will occur. */
	@Prop() shiftPadding = 0;

	/** When set, this will cause the popup to automatically resize itself to prevent it from overflowing. */
	@Prop() autoSize: "horizontal" | "vertical" | "both";

	/** Syncs the popup's width or height to that of the anchor element. */
	@Prop() sync: "width" | "height" | "both";

	/**
	 * The auto-size boundary describes clipping element(s) that overflow will be checked relative to when resizing. By
	 * default, the boundary includes overflow ancestors that will cause the element to be clipped. If needed, you can
	 * change the boundary by passing a reference to one or more elements to this property.
	 */
	@Prop() autoSizeBoundary: HTMLElement | HTMLElement[];

	/** The amount of padding, in pixels, to exceed before the auto-size behavior will occur. */
	@Prop() autoSizePadding = 0;

	@Prop() composed = false;

	/** event emitted when any of navigational elements are clicked. event.detail has the "type" of change event and clicked "step" */
	@Event({ eventName: "hbr-reposition" }) hbrReposition: EventEmitter;

	/** Emitted when the resolved popup placement differs from the requested placement. */
	@Event({ eventName: "hbr-placement-change", bubbles: true, composed: true })
	hbrPlacementChange: EventEmitter<{
		placement: string;
		currentPlacement: string;
	}>;

	/** Emitted when outside of popup is clicked or escape key is pressed. Usually listen for this event to close the popup. */
	@Event({ eventName: "hbr-popup-hide" }) hbrPopupHide: EventEmitter;

	/** Emitted when inside of popup (including anchor element) is clicked. Usually listen for this event to open the popup. */
	@Event({ eventName: "hbr-popup-show" }) hbrPopupShow: EventEmitter;

	@Event({ eventName: "hbr-arrow-mouseleave" })
	arrowMouseleave: EventEmitter;
	@Event({ eventName: "hbr-arrow-mouseenter" })
	arrowMouseenter: EventEmitter;

	@Listen("mousedown", { target: "document" })
	handleMousedown(event) {
		const path = event.composedPath();
		const component = this.host.hasAttribute("data-component");
		const select = component && this.host.hasAttribute("data-component");
		this.host.getAttribute("data-component") === "hbr-select";
		const externalAnchor =
			select && this.host.getAttribute("data-external-anchor");
		// Avoid unnecessary event listeners on select
		if (select && !externalAnchor) {
			return;
		}

		if (path.includes(this.host)) {
			this.hbrPopupShow.emit({
				type: "inside-click",
				component,
				externalAnchor,
			});
		} else {
			if (
				!(this.anchor instanceof HTMLElement) &&
				path.includes(this.anchorRef)
			) {
				/** external */
				this.hbrPopupShow.emit({
					type: "inside-click",
					component,
					externalAnchor,
				});
			} else {
				this.hbrPopupHide.emit({
					type: "outside-click",
					component,
					externalAnchor,
				});
			}
		}
	}

	/** A reference to the internal popup container. Useful for animating and styling the popup with JavaScript. */
	private popupRef: HTMLElement;
	private arrowRef: HTMLElement;
	private arrowOverlayRef: HTMLElement;
	private anchorRef; /**  : HTMLElement | null; */
	private cleanup: (() => void) | undefined;

	connectedCallback() {
		this.handleAnchorChange = this.handleAnchorChange.bind(this);
	}

	componentDidLoad() {
		this.handleAnchorChange();
	}

	componentDidUpdate() {
		// All other properties will trigger a reposition when active
		if (this.active) {
			this.reposition();
		}
	}

	@Watch("anchor")
	handleAnchorChange() {
		this.stop();

		if (this.anchor && typeof this.anchor === "string") {
			// Locate the anchor by querySelector
			this.anchorRef = document?.querySelector(this.anchor);
		} else if (
			this.anchor instanceof HTMLElement ||
			this.anchor instanceof SVGElement
		) {
			// Use the anchor's reference
			this.anchorRef = this.anchor;
		} else {
			// Look for a slotted anchor
			this.anchorRef = this.host.querySelector<HTMLElement>('[slot="anchor"]');
		}

		if (this.enablePopover && this.anchorRef) {
			this.anchorRef.popoverTargetElement = this.popupRef;
		}

		// If the anchor is a <slot>, we'll use the first assigned element as the target since slots use `display: contents`
		// and positioning can't be calculated on them
		if (this.anchorRef instanceof HTMLSlotElement) {
			this.anchorRef = this.anchorRef.assignedElements({
				flatten: true,
			})[0] as HTMLElement;
		}

		if (!this.anchorRef) {
			console.warn(
				"Invalid anchor element: no anchor could be found using the anchor slot or the anchor attribute.",
			);
		}

		this.start();
	}

	async start() {
		// We can't start the positioner without an anchor
		if (!this.anchorRef) {
			return;
		}

		const anchorRef = this.anchorRef;
		const popupRef = this.popupRef;

		if (!anchorRef || !popupRef) {
			return;
		}

		const { autoUpdate } = await loadFloatingUi();

		if (anchorRef !== this.anchorRef || popupRef !== this.popupRef) {
			return;
		}

		this.cleanup = autoUpdate(anchorRef, popupRef, () => {
			void this.reposition();
		});
	}

	stop() {
		return new Promise((resolve) => {
			if (this.cleanup) {
				this.cleanup();
				this.cleanup = undefined;
				this.currentPlacement = null;
				this.host.removeAttribute("data-current-placement");
				this.host.style.removeProperty("--auto-size-available-width");
				this.host.style.removeProperty("--auto-size-available-height");
				requestAnimationFrame(() => resolve(null));
			} else {
				resolve(null);
			}
		});
	}

	@Watch("active")
	async handleActiveChange() {
		if (this.active) {
			if (this.enablePopover && this.popupRef) {
				this.popupRef.showPopover();
			}
			await this.start();
		} else {
			if (this.enablePopover && this.popupRef) {
				this.popupRef.hidePopover();
			}
			await this.stop();
		}
	}

	@Watch("placement")
	handlePlacementChange() {
		if (this.active) {
			this.reposition();
		}
	}

	@Watch("arrow")
	handleArrowChange() {
		if (this.active) {
			this.reposition();
		}
	}

	/** Forces the popup to recalculate and reposition itself. */
	@Method()
	async reposition() {
		// Nothing to do if the popup is inactive or the anchor doesn't exist
		if (!this.active || !this.anchorRef) {
			return;
		}

		const { arrow, computePosition, flip, offset, platform, shift, size } =
			await loadFloatingUi();

		//
		// NOTE: Floating UI middlewares are order dependent: https://floating-ui.com/docs/middleware
		//
		const middleware = [
			// The offset middleware goes first
			offset({
				mainAxis: this.arrow ? this.arrowSize + this.distance : this.distance,
				crossAxis: this.skidding,
			}),
		];

		// First we sync width/height
		if (this.sync) {
			middleware.push(
				size({
					apply: ({ rects }) => {
						const syncWidth = this.sync === "width" || this.sync === "both";
						const syncHeight = this.sync === "height" || this.sync === "both";
						this.popupRef.style.width = syncWidth
							? `${rects.reference.width}px`
							: "";
						this.popupRef.style.height = syncHeight
							? `${rects.reference.height}px`
							: "";
					},
				}),
			);
		} else {
			// Cleanup styles if we're not matching width/height
			this.popupRef.style.width = "";
			this.popupRef.style.height = "";
		}

		// Then we flip
		if (this.flip) {
			middleware.push(
				flip({
					boundary: this.flipBoundary,
					// // @ts-expect-error - We're converting a string attribute to an array here
					// fallbackPlacements: this.flipFallbackPlacements,
					fallbackStrategy:
						this.flipFallbackStrategy === "best-fit"
							? "bestFit"
							: "initialPlacement",
					padding: this.flipPadding,
				}),
			);
		}

		// Then we shift
		if (this.shift) {
			middleware.push(
				shift({
					boundary: this.shiftBoundary,
					padding: this.shiftPadding,
				}),
			);
		}

		// Now we adjust the size as needed
		// TODO - readdress this logic at 319
		if (this.autoSize) {
			middleware.push(
				size({
					boundary: this.autoSizeBoundary,
					padding: this.autoSizePadding,
					apply: ({ availableWidth, availableHeight }) => {
						if (this.autoSize === "vertical" || this.autoSize === "both") {
							this.host.style.setProperty(
								"--auto-size-available-height",
								`${Math.max(availableHeight, this.autoSizePadding || 0)}px`,
							);
						} else {
							this.host.style.removeProperty("--auto-size-available-height");
						}

						if (this.autoSize === "horizontal" || this.autoSize === "both") {
							this.host.style.setProperty(
								"--auto-size-available-width",
								`${availableWidth}px`,
							);
						} else {
							this.host.style.removeProperty("--auto-size-available-width");
						}
					},
				}),
			);
		} else {
			// Cleanup styles if we're no longer using auto-size
			this.host.style.removeProperty("--auto-size-available-width");
			this.host.style.removeProperty("--auto-size-available-height");
		}

		// Finally, we add an arrow
		if (this.arrow) {
			middleware.push(
				arrow({
					element: this.arrowRef,
					padding: this.arrowPadding,
				}),
			);
		}

		//
		// Use custom positioning logic if the strategy is absolute. Otherwise, fall back to the default logic.
		//
		// More info: https://github.com/shoelace-style/shoelace/issues/1135
		//
		const getOffsetParent =
			this.strategy === "absolute"
				? (element: HTMLElement) =>
						platform.getOffsetParent(element, offsetParent)
				: platform.getOffsetParent;

		computePosition(this.anchorRef, this.popupRef, {
			placement: this.placement,
			middleware,
			strategy: this.strategy,
			platform: {
				...platform,
				getOffsetParent,
			},
		}).then(({ x, y, middlewareData, placement }) => {
			//
			// Even though we have our own localization utility, it uses different heuristics to determine RTL. Because of
			// that, we'll use the same approach that Floating UI uses.
			//
			// Source: https://github.com/floating-ui/floating-ui/blob/cb3b6ab07f95275730d3e6e46c702f8d4908b55c/packages/dom/src/utils/getDocumentRect.ts#L31
			//
			const isRtl = getComputedStyle(this.host).direction === "rtl";
			// biome-ignore lint/style/noNonNullAssertion: unknown
			const staticSide = {
				top: "bottom",
				right: "left",
				bottom: "top",
				left: "right",
			}[placement.split("-")[0]]!;

			const previousPlacement = this.currentPlacement;
			this.currentPlacement = placement;
			this.host.setAttribute("data-current-placement", placement);

			if (this.placement !== placement && previousPlacement !== placement) {
				this.hbrPlacementChange.emit({
					placement: this.placement,
					currentPlacement: placement,
				});
			}

			Object.assign(this.popupRef.style, {
				left: `${x}px`,
				top: `${y}px`,
			});

			if (this.arrow) {
				const arrowX = middlewareData.arrow?.x;
				const arrowY = middlewareData.arrow?.y;
				let top = "";
				let right = "";
				let bottom = "";
				let left = "";

				if (this.arrowPlacement === "start") {
					// Start
					const value =
						typeof arrowX === "number" ? `${this.arrowPadding}px` : "";
					top = typeof arrowY === "number" ? `${this.arrowPadding}px` : "";
					right = isRtl ? value : "";
					left = isRtl ? "" : value;
				} else if (this.arrowPlacement === "end") {
					// End
					const value =
						typeof arrowX === "number" ? `${this.arrowPadding}px` : "";
					right = isRtl ? "" : value;
					left = isRtl ? value : "";
					bottom = typeof arrowY === "number" ? `${this.arrowPadding}px` : "";
				} else if (this.arrowPlacement === "center") {
					// Center
					left =
						typeof arrowX === "number" ? "calc(50% - var(--arrow-size))" : "";
					top =
						typeof arrowY === "number" ? "calc(50% - var(--arrow-size))" : "";
				} else {
					// Anchor (default)
					left = typeof arrowX === "number" ? `${arrowX}px` : "";
					top = typeof arrowY === "number" ? `${arrowY}px` : "";
				}

				Object.assign(this.arrowRef.style, {
					top,
					right,
					bottom,
					left,
					[staticSide]:
						"calc(var(--arrow-size) * -1 + var(--arrow-border-overlap, 0px))",
				});

				/** for onHover use case */
				if (this.arrowOverlayRef) {
					Object.assign(this.arrowOverlayRef.style, {
						top,
						right,
						bottom,
						left,
						[staticSide]:
							"calc(var(--arrow-size) * -1 + var(--arrow-border-overlap, 0px))",
					});
					const { height, width } =
						this.arrowRef?.getBoundingClientRect() || {};
					const { distance } = this;
					const { style } = this.arrowRef || {};
					if (height && width && style) {
						const overlayPadding = 4; // Extra padding for easier hovering
						const overlayWidth = overlayPadding * 4;
						const overlayOffset = overlayWidth / 1.5;
						if (staticSide === "top") {
							this.arrowOverlayRef.style.top = `${-(
								height / 2 +
								distance +
								overlayPadding
							)}px`;
							this.arrowOverlayRef.style.height = `${
								height + distance + overlayPadding
							}px`;
							this.arrowOverlayRef.style.width = `${width + overlayWidth}px`;
							this.arrowOverlayRef.style.left = `${
								typeof arrowX === "number"
									? arrowX - overlayOffset
									: -overlayOffset
							}px`;
						} else if (staticSide === "bottom") {
							this.arrowOverlayRef.style.bottom = `${
								-height / 2 - distance - overlayPadding
							}px`;
							this.arrowOverlayRef.style.height = `${
								height + distance + overlayPadding
							}px`;
							this.arrowOverlayRef.style.width = `${width + overlayWidth}px`;
							this.arrowOverlayRef.style.left = `${
								typeof arrowX === "number"
									? arrowX - overlayOffset
									: -overlayOffset
							}px`;
						} else if (staticSide === "left") {
							this.arrowOverlayRef.style.left = `${-(
								width / 2 +
								distance +
								overlayPadding
							)}px`;
							this.arrowOverlayRef.style.width = `${
								width + distance + overlayPadding
							}px`;
							this.arrowOverlayRef.style.height = `${height + overlayWidth}px`;
							this.arrowOverlayRef.style.top = `${
								typeof arrowY === "number"
									? arrowY - overlayOffset
									: -overlayOffset
							}px`;
						} else if (staticSide === "right") {
							this.arrowOverlayRef.style.right = `${
								-width / 2 - distance - overlayPadding
							}px`;
							this.arrowOverlayRef.style.width = `${
								width + distance + overlayPadding
							}px`;
							this.arrowOverlayRef.style.height = `${height + overlayWidth}px`;
							this.arrowOverlayRef.style.top = `${
								typeof arrowY === "number"
									? arrowY - overlayOffset
									: -overlayOffset
							}px`;
						}
					}
				}
			}
		});

		this.hbrReposition.emit();
	}

	handleKeyDown(event: KeyboardEvent) {
		if (event.key === "Escape" || event.key === "Esc") {
			this.hbrPopupHide.emit({ type: "escape" });
		}
	}

	render() {
		return (
			<Host>
				<slot name="anchor" onSlotchange={this.handleAnchorChange} />

				<div
					part="popup"
					ref={(el) => {
						this.popupRef = el;
						if (this.enablePopover && this.popupRef) {
							this.popupRef.popover = "manual";
						}
					}}
					class={{
						popup: true,
						"popup--active": this.active,
						"popup--fixed": this.strategy === "fixed",
						"popup--has-arrow": this.arrow,
					}}
					onKeyDown={this.handleKeyDown.bind(this)}
				>
					{this.arrow ? (
						<Fragment>
							<div
								part="arrow"
								ref={(el) => {
									this.arrowRef = el;
								}}
								class="popup__arrow"
								role="presentation"
							/>
							<div
								class={"arrow__overlay"}
								onMouseLeave={() => {
									this.arrowMouseleave.emit();
								}}
								onMouseEnter={() => {
									this.arrowMouseenter.emit();
								}}
								ref={(el) => {
									this.arrowOverlayRef = el;
								}}
							/>
						</Fragment>
					) : null}
					<slot />
				</div>
			</Host>
		);
	}
}

declare global {
	interface HTMLElementTagNameMap {
		"hbr-popup": HTMLHbrPopupElement;
	}
}
